}
public static long func( long x ) {
if ( map.containsKey( x ) ) return map.get( x ) ;
long res = ( ( func( floor( x ) ) % mod ) * ( func( ceil( x ) ) % mod ) ) % mod ;
map.put( x , res ) ;
return res ;
}
public static long floor( long x ) {
return x / 2L ;
}
public static long ceil( long x ) {
return ( x + 1L ) / 2L ;
}
}

